const en=document.documentElement.lang==='en',t=(sk,english)=>en?english:sk;
let adminToken='';try{adminToken=sessionStorage.getItem('fedoracing-admin')||'';}catch{}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(adminToken?{Authorization:'Bearer '+adminToken}:{}),...options.headers}});let data;try{data=await response.json();}catch{throw Error(t('Služba momentálne nie je dostupná. Skúste to neskôr alebo nás kontaktujte.','Service is temporarily unavailable. Please try later or contact us.'));}if(!response.ok)throw Error(data.error||'Request failed');return data;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat(en?'en-IE':'sk-SK',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const cat=x=>({drift:'Drift',race:t('Preteky / okruh','Race / track'),road:t('Cestné auto','Road car'),news:t('Novinky','News'),blog:'Blog',event:t('Akcia','Event')})[x]||x;
const empty=(heading,body)=>`<div class="empty-state"><strong>${esc(heading)}</strong>${esc(body)}</div>`;
const dialog=document.querySelector('#detail-dialog');dialog?.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
let cars=[],posts=[],newsFilter='all';
function showCar(c){document.querySelector('#detail-content').innerHTML=`<p class="eyebrow red">${esc(cat(c.category))}</p><h2>${esc(c.title)}</h2><h3>${esc(money(c.price))}</h3><div class="spec-row"><span>${esc(c.year)}</span><span>${esc(c.power)} kW</span><span>${esc(c.mileage)} km</span><span>${esc(c.location)}</span></div><div class="detail-gallery">${c.photos.map(p=>`<img src="/api/photos/${encodeURI(p)}" alt="${esc(c.title)}">`).join('')}</div><p class="detail-copy">${esc(c.description)}</p><div class="detail-contact"><strong>${esc(c.seller)}</strong><a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${esc(c.phone)}</a><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></div>`;dialog.showModal();}
function renderCars(){const query=document.querySelector('#car-search').value.trim().toLowerCase(),category=document.querySelector('#car-category').value;const filtered=cars.filter(c=>(category==='all'||c.category===category)&&`${c.title} ${c.make} ${c.model}`.toLowerCase().includes(query));document.querySelector('#listing-count').textContent=`${filtered.length} ${t('inzerátov','listings')}`;const box=document.querySelector('#listings');box.innerHTML=filtered.length?filtered.map(c=>`<article class="market-card">${c.photos?.length?`<img src="/api/photos/${encodeURI(c.photos[0])}" alt="${esc(c.title)}" loading="lazy">`:`<div class="no-photo">FEDORACING</div>`}<div class="market-card-body"><p class="eyebrow red">${esc(cat(c.category))}</p><h3>${esc(c.title)}</h3><div class="price">${esc(money(c.price))}</div><div class="spec-row"><span>${esc(c.year)}</span><span>${esc(c.power)} kW</span><span>${esc(c.mileage)} km</span></div><p>${esc(c.location)}</p><button data-car="${esc(c.id)}">${t('POZRIEŤ AUTO','VIEW CAR')} <span>↗</span></button></div></article>`).join(''):empty(t('Vaše ďalšie auto príde čoskoro.','Your next car is on its way.'),t('Zatiaľ tu nie sú schválené inzeráty zodpovedajúce výberu. Pridajte prvý alebo upravte filter.','No approved listings match this selection yet. Submit the first one or change the filter.'));box.querySelectorAll('[data-car]').forEach(b=>b.addEventListener('click',()=>showCar(cars.find(c=>c.id===b.dataset.car))));}
if(document.body.dataset.page==='cars'){
 api('/api/listings').then(data=>{cars=data;renderCars();}).catch(e=>document.querySelector('#listings').innerHTML=empty(t('Ponuku sa nepodarilo načítať.','Could not load listings.'),e.message));
 document.querySelector('#car-search').addEventListener('input',renderCars);document.querySelector('#car-category').addEventListener('change',renderCars);
 let previews=[];document.querySelector('#listing-photos').addEventListener('change',e=>{previews.forEach(URL.revokeObjectURL);previews=[];const box=document.querySelector('#photo-previews');box.replaceChildren();const files=[...e.target.files];if(files.length>4||files.some(f=>f.size>5*1024*1024)){e.target.setCustomValidity(t('Najviac 4 fotografie, každá do 5 MB.','Maximum 4 photos, 5 MB each.'));e.target.reportValidity();return;}e.target.setCustomValidity('');for(const f of files){const u=URL.createObjectURL(f);previews.push(u);const img=document.createElement('img');img.src=u;img.alt=f.name;box.append(img);}});
 document.querySelector('#listing-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]'),status=document.querySelector('#listing-status');button.disabled=true;status.textContent=t('Odosielam inzerát…','Submitting your listing…');try{const result=await api('/api/listings',{method:'POST',body:new FormData(e.target)});status.textContent=t('Inzerát bol uložený a čaká na schválenie. Číslo inzerátu: ','Your listing is saved and awaiting approval. Reference: ')+result.id;e.target.reset();previews.forEach(URL.revokeObjectURL);previews=[];document.querySelector('#photo-previews').replaceChildren();}catch(error){status.textContent=t('Inzerát sa neodoslal. ','The listing was not submitted. ')+error.message;}finally{button.disabled=false;}});
}
function showPost(p){const translated=en&&p.bodyEn;document.querySelector('#detail-content').innerHTML=`<p class="eyebrow red">${esc(cat(p.category))}${p.eventDate?' · '+esc(p.eventDate):''}</p><h2>${esc(en&&p.titleEn?p.titleEn:p.title)}</h2>${en&&!translated?'<p class="post-language-note">This article is available in Slovak.</p>':''}<div class="detail-copy">${esc(translated?p.bodyEn:p.body)}</div>`;dialog.showModal();history.replaceState(null,'','#'+p.id);}
function renderPosts(){const data=posts.filter(p=>newsFilter==='all'||p.category===newsFilter);const box=document.querySelector('#posts');box.innerHTML=data.length?data.map(p=>`<article class="post-card"><p class="eyebrow red">${esc(cat(p.category))}${p.eventDate?' · '+esc(p.eventDate):''}</p><h3>${esc(en&&p.titleEn?p.titleEn:p.title)}</h3><p>${esc((en&&p.bodyEn?p.bodyEn:p.body).slice(0,190))}…</p><button data-post="${esc(p.id)}">${t('ČÍTAŤ ĎALEJ','READ MORE')} ↗</button></article>`).join(''):empty(t('Ďalší príbeh už pripravujeme.','The next story is coming.'),t('Novinky, články a termíny akcií tu pribudnú po publikovaní. Zatiaľ nás sledujte na Instagrame.','News, articles and event dates will appear here when published. Follow us on Instagram in the meantime.'));box.querySelectorAll('[data-post]').forEach(b=>b.addEventListener('click',()=>showPost(posts.find(p=>p.id===b.dataset.post))));}
if(document.body.dataset.page==='news'){api('/api/posts').then(data=>{posts=data;renderPosts();const p=posts.find(p=>p.id===location.hash.slice(1));if(p)showPost(p);}).catch(e=>document.querySelector('#posts').innerHTML=empty(t('Články sa nepodarilo načítať.','Could not load articles.'),e.message));document.querySelectorAll('[data-news-filter]').forEach(b=>b.addEventListener('click',()=>{newsFilter=b.dataset.newsFilter;document.querySelectorAll('[data-news-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderPosts();}));}
let adminPhotos=[];
async function loadAdmin(){try{const session=await api('/api/session');document.querySelector('#sites-signin').hidden=!session.sites;document.querySelector('#admin-login').hidden=session.admin;document.querySelector('#admin-content').hidden=!session.admin;document.querySelector('#admin-logout').hidden=!adminToken;if(!session.admin){document.querySelector('#admin-status').textContent='Prihláste sa ako správca. Obsah nie je verejne prístupný.';return;}document.querySelector('#admin-status').textContent='Prihlásenie správcu overené.';const [list,articles]=await Promise.all([api('/api/admin/listings'),api('/api/admin/posts')]);adminPhotos.forEach(URL.revokeObjectURL);adminPhotos=[];const box=document.querySelector('#admin-listings');box.innerHTML=list.length?list.map(c=>`<article class="admin-item"><span class="admin-status-badge">${esc(c.status)} · ${esc(c.id)}</span><h3>${esc(c.title)} · ${esc(money(c.price))}</h3><p>${esc(c.make)} ${esc(c.model)} / ${esc(c.year)} / ${esc(c.power)} kW / ${esc(c.mileage)} km / ${esc(c.location)}</p><p>${esc(c.description)}</p><p>${esc(c.seller)} · ${esc(c.email)} · ${esc(c.phone)}</p><div class="admin-gallery" data-gallery="${esc(c.id)}"></div><button data-id="${esc(c.id)}" data-state="published">Schváliť / zverejniť</button><button data-id="${esc(c.id)}" data-state="rejected">Zamietnuť / skryť</button><button data-id="${esc(c.id)}" data-state="sold">Označiť predané</button><button data-id="${esc(c.id)}" data-state="pending">Vrátiť na kontrolu</button></article>`).join(''):'<p>Žiadne inzeráty na kontrolu.</p>';
 for(const c of list){const gallery=box.querySelector(`[data-gallery="${c.id}"]`);for(const key of c.photos||[]){const response=await fetch('/api/photos/'+encodeURI(key),{headers:adminToken?{Authorization:'Bearer '+adminToken}:{}});if(response.ok){const u=URL.createObjectURL(await response.blob());adminPhotos.push(u);const img=document.createElement('img');img.src=u;img.alt=c.title;gallery.append(img);}}}
 box.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api('/api/admin/listings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.id,status:b.dataset.state})});await loadAdmin();}catch(e){document.querySelector('#admin-status').textContent=e.message;b.disabled=false;}}));
 document.querySelector('#admin-posts').innerHTML=articles.map(p=>`<article class="admin-item"><span class="admin-status-badge">${esc(p.status)} · ${esc(cat(p.category))}</span><h3>${esc(p.title)}</h3><button data-edit-post="${esc(p.id)}">Upraviť / zmeniť stav</button></article>`).join('');document.querySelectorAll('[data-edit-post]').forEach(b=>b.addEventListener('click',()=>{const p=articles.find(p=>p.id===b.dataset.editPost),f=document.querySelector('#post-form');for(const [key,value]of Object.entries(p))if(f.elements.namedItem(key))f.elements.namedItem(key).value=value;f.scrollIntoView({behavior:'smooth'});}));
 }catch(e){document.querySelector('#admin-content').hidden=true;document.querySelector('#admin-status').textContent=e.message;}}
if(document.body.dataset.page==='admin'){loadAdmin();document.querySelector('#admin-key-form').addEventListener('submit',e=>{e.preventDefault();adminToken=document.querySelector('#admin-key').value.trim();try{sessionStorage.setItem('fedoracing-admin',adminToken);}catch{}document.querySelector('#admin-key').value='';loadAdmin();});document.querySelector('#admin-logout').addEventListener('click',()=>{adminToken='';try{sessionStorage.removeItem('fedoracing-admin');}catch{}loadAdmin();});document.querySelector('#post-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));await api('/api/admin/posts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});document.querySelector('#post-status').textContent='Článok bol uložený.';e.target.reset();await loadAdmin();}catch(error){document.querySelector('#post-status').textContent=error.message;}finally{button.disabled=false;}});}
